OUT.sort(key=lambda x:x['id'])
assert len(OUT)==19 and {x['id'] for x in OUT}==set(INPUT)
for p in OUT:
    assert p['sources'] and all(s['url'].startswith('https://') for s in p['sources'])
    for lc in ('ar','en'):
        d=p[lc]
        assert len(d['benefits'])==3 and len(d['steps'])==3 and len(d['faq'])==2
        assert 2<=len(d['ingredients'])<=4
        assert all(isinstance(v,str) and v.strip() for k,v in d.items() if k not in ('benefits','steps','ingredients','faq'))
        assert len(d['description'])<=1200 and len(d['notes'])<=1200
    assert not any('video' in k.lower() for k in p)
(ROOT/'content-2.json').write_text(json.dumps(OUT,ensure_ascii=False,indent=2)+'\n')
print(json.dumps({'products':len(OUT),'output':str(ROOT/'content-2.json'),'bytes':(ROOT/'content-2.json').stat().st_size,'status':'validated'},ensure_ascii=False))
